class Solution {
public:
    int maxScore(vector<vector<int>>& grid) {
        int m = grid.size();
        unordered_map<int, vector<int>> val_rows;
        for (int r = 0; r < m; ++r) {
            unordered_set<int> unique_row(grid[r].begin(), grid[r].end());
            for (int v : unique_row) {
                val_rows[v].push_back(r);
            }
        }
        vector<int> vals;
        for (const auto& [v, _] : val_rows) vals.push_back(v);
        sort(vals.rbegin(), vals.rend());

        vector<int> dp(1 << m, -1);
        dp[0] = 0;

        for (int v : vals) {
            vector<int> next_dp = dp;
            const auto& rows = val_rows[v];
            for (int mask = 0; mask < (1 << m); ++mask) {
                if (dp[mask] == -1) continue;
                for (int r : rows) {
                    if (!(mask & (1 << r))) {
                        int new_mask = mask | (1 << r);
                        next_dp[new_mask] = max(next_dp[new_mask], dp[mask] + v);
                    }
                }
            }
            dp = move(next_dp);
        }
        int ans = 0;
        for (int score : dp) ans = max(ans, score);
        return ans;
    }
};

class Solution {
    public int maxScore(int[][] grid) {
        int m = grid.length;
        Map<Integer, List<Integer>> valRows = new HashMap<>();
        for (int r = 0; r < m; ++r) {
            Set<Integer> unique = new HashSet<>();
            for (int v : grid[r]) unique.add(v);
            for (int v : unique) {
                valRows.computeIfAbsent(v, k -> new ArrayList<>()).add(r);
            }
        }
        List<Integer> vals = new ArrayList<>(valRows.keySet());
        vals.sort(Collections.reverseOrder());

        int[] dp = new int[1 << m];
        Arrays.fill(dp, -1);
        dp[0] = 0;

        for (int v : vals) {
            int[] nextDp = dp.clone();
            List<Integer> rows = valRows.get(v);
            for (int mask = 0; mask < (1 << m); ++mask) {
                if (dp[mask] == -1) continue;
                for (int r : rows) {
                    if ((mask & (1 << r)) == 0) {
                        int newMask = mask | (1 << r);
                        nextDp[newMask] = Math.max(nextDp[newMask], dp[mask] + v);
                    }
                }
            }
            dp = nextDp;
        }
        int ans = 0;
        for (int s : dp) ans = Math.max(ans, s);
        return ans;
    }
}

var maxScore = function(grid) {
    const m = grid.length;
    const valRows = new Map();
    for (let r = 0; r < m; r++) {
        const unique = new Set(grid[r]);
        for (const v of unique) {
            if (!valRows.has(v)) valRows.set(v, []);
            valRows.get(v).push(r);
        }
    }
    const vals = Array.from(valRows.keys()).sort((a, b) => b - a);
    let dp = new Array(1 << m).fill(-1);
    dp[0] = 0;

    for (const v of vals) {
        const nextDp = [...dp];
        const rows = valRows.get(v);
        for (let mask = 0; mask < (1 << m); mask++) {
            if (dp[mask] === -1) continue;
            for (const r of rows) {
                if (!(mask & (1 << r))) {
                    const newMask = mask | (1 << r);
                    nextDp[newMask] = Math.max(nextDp[newMask], dp[mask] + v);
                }
            }
        }
        dp = nextDp;
    }
    return Math.max(...dp);
};
